// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }

    function testFuzz_property(uint256 amount, uint256 padding) public {
        vm.assume(padding <= VALUE_CAP);
        // Admissible domain: deposit d, withdraw a with 2 <= a <= d, plus unrelated padding funds held by c.
        uint256 d = 100 ether;
        amount = bound(amount, 2, d);
        padding = bound(padding, 1 ether, 10 ether);

        address actor = address(0xA11cE);

        // Unrelated padding so the contract can always pay out any amount it is willing to send.
        vm.deal(address(this), padding);
        c.deposit{value: padding}();

        // Actor deposits d and then withdraws a.
        vm.deal(actor, d);
        vm.prank(actor);
        c.deposit{value: d}();
        vm.prank(actor);
        c.withdraw(amount);

        // General rule: the caller can never withdraw more than the remaining balance d - amount,
        // regardless of extra funds the contract holds for other depositors.
        bool ok;
        vm.prank(actor);
        try c.withdraw(d - amount + 1) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "over-withdrawal beyond remaining balance must revert");
    }
}
